<?php $pageTitle='Employee Workspace';$subtitle='Your work, deliveries and attendance in one place.';require __DIR__.'/_guard.php';$pdo=db();$me=$pdo->prepare('SELECT * FROM users WHERE id=?');$me->execute([(int)$user['id']]);$profile=$me->fetch();$today=$pdo->prepare('SELECT * FROM attendance WHERE employee_id=? AND attendance_date=? LIMIT 1');$today->execute([(int)$user['id'],date('Y-m-d')]);$att=$today->fetch();$monthStart=date('Y-m-01');$todayDate=date('Y-m-d');$daysElapsed=(int)date('j');$monthStmt=$pdo->prepare("SELECT COUNT(*) records,SUM(CASE WHEN status='present' THEN 1 ELSE 0 END) present,SUM(CASE WHEN status='rejected' THEN 1 ELSE 0 END) rejected,SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END) pending FROM attendance WHERE employee_id=? AND attendance_date BETWEEN ? AND ?");$monthStmt->execute([(int)$user['id'],$monthStart,$todayDate]);$monthStats=$monthStmt->fetch();$presentDays=(int)($monthStats['present']??0);$attendancePct=$daysElapsed>0?min(100,round($presentDays/$daysElapsed*100,1)):0;$attHistoryStmt=$pdo->prepare("SELECT * FROM attendance WHERE employee_id=? ORDER BY attendance_date DESC LIMIT 30");$attHistoryStmt->execute([(int)$user['id']]);$attHistory=$attHistoryStmt->fetchAll();$assign=$pdo->prepare("SELECT ea.*,o.order_number,o.customer_name,o.pincode FROM employee_assignments ea LEFT JOIN orders o ON o.id=ea.order_id WHERE ea.employee_id=? ORDER BY CASE ea.status WHEN 'assigned' THEN 1 WHEN 'accepted' THEN 2 WHEN 'in_progress' THEN 3 ELSE 4 END,ea.due_at IS NULL,ea.due_at");$assign->execute([(int)$user['id']]);$jobs=$assign->fetchAll();$open=array_filter($jobs,fn($x)=>!in_array($x['status'],['completed','cancelled'],true));$deliveries=array_filter($jobs,fn($x)=>$x['assignment_type']==='delivery');?>
<!doctype html><html lang="en"><head><link rel="icon" type="image/png" sizes="256x256" href="../data/favicon.png"><link rel="apple-touch-icon" href="../data/favicon.png"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#070a10"><title>Employee Workspace — Swarnim Groups</title><link rel="stylesheet" href="../admin/style.css"><style>.employee .side{border-right-color:rgba(117,183,255,.16)}.hero{padding:28px;background:linear-gradient(135deg,rgba(117,183,255,.12),rgba(244,197,66,.07));border:1px solid rgba(117,183,255,.15);border-radius:22px;margin-bottom:18px}.att{display:flex;justify-content:space-between;gap:18px;align-items:center}.gps{font-size:12px;color:var(--muted);margin-top:8px}.job{padding:17px 0;border-bottom:1px solid var(--line)}.job:last-child{border-bottom:0}.job-top{display:flex;justify-content:space-between;gap:10px}.job h3{margin:0 0 6px;font-size:16px}.job p{margin:0;color:var(--muted);font-size:13px;line-height:1.6}.status-btns{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}@media(max-width:680px){.att{align-items:flex-start;flex-direction:column}.hero{padding:20px}}
.employee-attendance-head{display:flex;align-items:center;justify-content:space-between;gap:20px}.employee-ring{width:108px;height:108px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--gold) var(--progress),rgba(255,255,255,.08) 0);position:relative;flex:0 0 auto}.employee-ring:after{content:'';position:absolute;inset:8px;border-radius:50%;background:var(--card)}.employee-ring>div{position:relative;z-index:1;text-align:center}.employee-ring strong{display:block;font-size:22px}.employee-ring span{display:block;color:var(--muted);font-size:10px;margin-top:2px}.employee-attendance-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:18px}.employee-attendance-stats div{padding:14px;border:1px solid var(--line);border-radius:15px;background:rgba(255,255,255,.025)}.employee-attendance-stats strong{display:block;font-size:20px}.employee-attendance-stats span{font-size:11px;color:var(--muted)}.employee-history{margin-top:20px;border-top:1px solid var(--line);padding-top:16px}.history-list{display:grid;gap:8px}.history-row{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:11px 0;border-bottom:1px solid var(--line)}.history-row>div{min-width:0}.history-row strong,.history-row small{display:block}.history-row small{color:var(--muted);font-size:10px;margin-top:3px}@media(max-width:680px){.employee-attendance-head{align-items:flex-start}.employee-ring{width:88px;height:88px}.employee-ring strong{font-size:18px}.employee-attendance-stats{grid-template-columns:repeat(2,1fr)}}</style></head><body class="employee"><div class="shell"><aside class="side"><a class="brand" href="index.php"><img src="../data/Swarnim Logo.png"><div><b>Swarnim Groups</b><span>Employee Workspace</span></div></a><nav class="nav"><a class="active" href="index.php"><i class="ico"><svg viewBox="0 0 24 24"><path d="M3 12l9-9 9 9M5 10v10h14V10M9 20v-6h6v6"/></svg></i><span>Dashboard</span></a><a href="#work"><i class="ico"><svg viewBox="0 0 24 24"><path d="M4 4h16v16H4zM8 8h8M8 12h8M8 16h5"/></svg></i><span>My Work</span></a><a href="#deliveries"><i class="ico"><svg viewBox="0 0 24 24"><path d="M3 6h11v11H3zM14 9h4l3 3v5h-7zM7 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4M17 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4"/></svg></i><span>Deliveries</span></a><a href="../profile.php"><i class="ico"><svg viewBox="0 0 24 24"><path d="M20 21a8 8 0 0 0-16 0M12 13a4 4 0 1 0 0-8 4 4 0 0 0 0 8"/></svg></i><span>Profile</span></a><a href="../logout.php"><i class="ico"><svg viewBox="0 0 24 24"><path d="M10 17l5-5-5-5M15 12H3M21 4v16"/></svg></i><span>Logout</span></a></nav></aside><main class="main"><div class="topbar"><div class="title"><h1>Welcome, <?=ee($profile['name'])?></h1><p>Field operations and attendance centre.</p></div><div class="user-chip"><span class="avatar"><?=ee(strtoupper(mb_substr($profile['name'],0,1)))?></span><span><?=ee($profile['name'])?></span></div></div><section class="hero"><div class="att"><div><div class="pill blue">Today · <?=date('d M Y')?></div><h2 style="margin:12px 0 5px">Attendance</h2><div id="attText" class="gps"><?php if($att):?>Status: <?=ee($att['status'])?> · Attempts: <?=ee($att['attempts'])?><?php else:?>Checking your location for today's attendance…<?php endif;?></div><div id="gpsInfo" class="gps"></div></div><button class="btn primary" id="markBtn" <?=($att&&$att['status']==='present')?'disabled':''?>><?=($att&&$att['status']==='present')?'Attendance Marked':'Mark Attendance'?></button></div></section><section class="card employee-attendance-card" style="margin-bottom:18px"><div class="employee-attendance-head"><div><div class="pill blue"><?=date('F Y')?> · Month to date</div><h2 style="margin:10px 0 4px">Attendance overview</h2><p class="gps">Present days divided by <?= $daysElapsed ?> elapsed calendar days.</p></div><div class="employee-ring" style="--progress:<?=$attendancePct?>%"><div><strong><?=$attendancePct?>%</strong><span>Present</span></div></div></div><div class="employee-attendance-stats"><div><strong><?=$presentDays?></strong><span>Present</span></div><div><strong><?=((int)$monthStats['pending'])?></strong><span>Pending</span></div><div><strong><?=((int)$monthStats['rejected'])?></strong><span>Rejected</span></div><div><strong><?=((int)$monthStats['records'])?></strong><span>Recorded</span></div></div><div class="employee-history"><div class="section-head"><h3>Recent attendance</h3><span class="pill gold">30 records</span></div><div class="history-list"><?php foreach($attHistory as $ah):?><div class="history-row"><div><strong><?=ee(date('d M Y',strtotime($ah['attendance_date'])))?></strong><small><?=ee($ah['marked_at'])?> · <?=ee($ah['method'])?></small></div><span class="pill <?=($ah['status']==='present'?'green':($ah['status']==='rejected'?'red':'gold'))?>"><?=ee($ah['status'])?></span></div><?php endforeach;if(!$attHistory):?><div class="empty">No attendance history yet.</div><?php endif;?></div></div></section><div class="grid stats"><div class="card stat"><div class="label">Open Work</div><strong><?=count($open)?></strong><small>Assigned tasks</small></div><div class="card stat"><div class="label">Deliveries</div><strong><?=count($deliveries)?></strong><small>Delivery jobs</small></div><div class="card stat"><div class="label">Today</div><strong><?= $att&&$att['status']==='present'?'Present':'Pending'?></strong><small>Attendance</small></div></div><div class="grid two" style="margin-top:18px"><section class="card" id="work"><div class="section-head"><h2>My Work</h2><span class="pill blue"><?=count($open)?> open</span></div><?php foreach($jobs as $j): if($j['assignment_type']!=='work')continue;?><article class="job"><div class="job-top"><div><h3><?=ee($j['title'])?></h3><p><?=ee($j['description'])?></p></div><span class="pill <?=in_array($j['priority'],['urgent','high'])?'red':'gold'?>"><?=ee($j['priority'])?></span></div><p style="margin-top:8px">Due: <?=ee($j['due_at']??'No due date')?> · Status: <?=ee($j['status'])?></p><div class="status-btns"><?php if($j['status']==='assigned'):?><button class="btn" onclick="updateJob(<?=$j['id']?>,'accepted')">Accept</button><?php endif;?><?php if(in_array($j['status'],['accepted','assigned'])):?><button class="btn blue" onclick="updateJob(<?=$j['id']?>,'in_progress')">Start Work</button><?php endif;?><?php if($j['status']==='in_progress'):?><button class="btn primary" onclick="updateJob(<?=$j['id']?>,'completed')">Complete</button><?php endif;?></div></article><?php endforeach;if(!$jobs||!array_filter($jobs,fn($x)=>$x['assignment_type']==='work')):?><div class="empty">No work has been assigned.</div><?php endif;?></section><section class="card" id="deliveries"><div class="section-head"><h2>Deliveries</h2><span class="pill green"><?=count($deliveries)?> jobs</span></div><?php foreach($jobs as $j): if($j['assignment_type']!=='delivery')continue;?><article class="job"><div class="job-top"><div><h3><?=ee($j['title'])?></h3><p><?=ee($j['address']??'')?></p><?php if($j['order_number']):?><p style="margin-top:5px">Order <?=ee($j['order_number'])?> · <?=ee($j['customer_name'])?> · PIN <?=ee($j['pincode'])?></p><?php endif;?></div><span class="pill <?=in_array($j['status'],['completed'])?'green':'blue'?>"><?=ee($j['status'])?></span></div><div class="status-btns"><?php if($j['status']==='assigned'):?><button class="btn" onclick="updateJob(<?=$j['id']?>,'accepted')">Accept Delivery</button><?php endif;?><?php if(in_array($j['status'],['accepted','assigned'])):?><button class="btn blue" onclick="updateJob(<?=$j['id']?>,'in_progress')">Out for Delivery</button><?php endif;?><?php if($j['status']==='in_progress'):?><button class="btn primary" onclick="updateJob(<?=$j['id']?>,'completed')">Mark Delivered</button><?php endif;?></div></article><?php endforeach;if(!$deliveries):?><div class="empty">No deliveries assigned.</div><?php endif;?></section></div></main></div><div id="toast" class="toast"></div><script>function toast(t,ok=true){const e=document.querySelector('#toast');e.textContent=t;e.className='toast show';e.style.borderColor=ok?'rgba(69,223,160,.35)':'rgba(255,102,120,.35)';setTimeout(()=>e.className='toast',3200)}const CSRF=<?=json_encode(csrfToken())?>;async function markAttendance(){const b=document.querySelector('#markBtn');if(!navigator.geolocation){toast('This device does not support location.',false);return}b.disabled=true;b.textContent='Reading location…';navigator.geolocation.getCurrentPosition(async pos=>{const fd=new FormData();fd.append('action','mark-attendance');fd.append('latitude',pos.coords.latitude);fd.append('longitude',pos.coords.longitude);fd.append('altitude',pos.coords.altitude??'');fd.append('accuracy',pos.coords.accuracy??'');const r=await fetch('api.php',{method:'POST',body:fd,headers:{'X-CSRF-Token':CSRF}});const j=await r.json();toast(j.message,j.ok);document.querySelector('#gpsInfo').textContent=j.data?.distance?`Distance from office: ${Number(j.data.distance).toFixed(1)} m · Allowed: ${j.data.radius} m`:'';if(j.ok){document.querySelector('#attText').textContent='Status: present';b.textContent='Attendance Marked';}else{b.disabled=false;b.textContent='Retry Attendance';document.querySelector('#attText').textContent=(j.data?.attempts?`Attempt ${j.data.attempts} of 4 · `:'')+(j.message||'');}},err=>{toast('Location permission is required to mark attendance.',false);b.disabled=false;b.textContent='Retry Attendance';document.querySelector('#gpsInfo').textContent=err.message});}async function updateJob(id,status){const fd=new FormData();fd.append('action','assignment-status');fd.append('id',id);fd.append('status',status);const r=await fetch('api.php',{method:'POST',body:fd,headers:{'X-CSRF-Token':CSRF}});const j=await r.json();toast(j.message,j.ok);if(j.ok)setTimeout(()=>location.reload(),500)}document.querySelector('#markBtn').addEventListener('click',markAttendance);<?php if(!$att||$att['status']!=='present'):?>setTimeout(markAttendance,700);<?php endif;?></script></body></html>
